// «הקוד פג תוקף»») — עבר QA 03.11.2026 пользователем (Android Pixel 6, app 1.0.0 (6) + OTA, SMS Pulseem).
// מה רצוי: F-39 AC1 «המוצר מציג למשתמש שהקוד נשלח ולאן»; F-39 AC4 / S-11 AC5 «שלח קוד מחדש» доступна, в т.ч. после ошибки;
// F-88 AC4 / S-11 AC4 неверный код — ошибка на иврите, остаёмся на экране кода, цифры не стёрты; тикет #5623bc: для неверного кода —
// «неверный», «פג תוקף» — только когда код действительно истёк; реджект #41747e — обходного режима нет (строки «מצב בדיקה» нет).
// Код 6 цифр — согласованное отличие от «ארבע ספרות» (context.md 26.10).
// Факт 03.11 (session-2026-11-03.json, otp-0311-android-01, -04): «הקוד בן שש הספרות נשלח למספר 0537240114», 6 клеток;
// «111111» сразу → «הקוד שהוזן אינו נכון. בדקו את שש הספרות שקיבלתם והזינו שוב, או בקשו קוד חדש.», клетки с цифрами, «שלח קוד מחדש» видна.
//
// Автоматически: всё, кроме ввода настоящего кода. Отправляет 1 платное SMS → QA_SMS=1 + QA_OTP_PHONE. @data: выходит из аккаунта.
// Конец: QA_OTP_MANUAL=1 — человек вводит код из SMS → главная (@manual-otp); иначе тест пытается вернуть вход USER1 через login().
// НЕ автоматизировано (по времени): неверный код через >60 с и код старше 300 с → «הקוד פג תוקף…» — ручной кейс AL-06 (шаги 4–5).
// Кейсы: .qa/tests/auth-login/AL-05-otp-code-screen-number.md, AL-06-otp-wrong-vs-expired.md.
import { expect } from '@wdio/globals';
import { byText, byTextContains } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn } from '../../helpers/app.ts';
import {
  requireSms, toPhoneScreen, submitPhone, waitCodeScreen, typeCode, tapSubmit, cellValues, expectHebrewMessage, expectNoTestMode,
  waitHumanFor, digitCell, OTP_PHONE, CODE_HINT, SENT_TO, RESEND, SUBMIT, WRONG_CODE, EXPIRED_CODE, BAD_CODE,
} from '../_lib/app-0311.ts';

describe('03.11 — экран кода: номер, неверный код (#41747e #5623bc)', function () {
  before(async function () { requireSms(this); });
  after(async function () {
    this.timeout(60000 + Number(process.env.QA_MANUAL_WAIT || 600000));
    if (await isLoggedIn()) return;
    if (process.env.QA_OTP_MANUAL === '1') {
      await waitHumanFor(`введите код из ПОСЛЕДНЕГО SMS на ${OTP_PHONE} и нажмите «שלח»`, ['__HOME__']).catch(() => {});
      return;
    }
    await ensureAppReady().catch((e) => console.log(`[Q-21] вход USER1 не восстановлен (${(e as Error).message}) — войти вручную`));
  });

  it('Q-21 Вход: номер → «שילחו קוד אימות» → «קוד אימות»: «הקוד בן שש הספרות נשלח למספר <номер>», 6 клеток, «שלח קוד מחדש», нет «מצב בדיקה»; «111111» сразу → «הקוד שהוזן אינו נכון…», не «פג תוקף», цифры на месте, «שלח קוד מחדש» доступна #41747e #5623bc @android @data @sms', async function () {
    this.timeout(180000);
    await toPhoneScreen();
    await submitPhone(OTP_PHONE);

    // F-39 AC1: показано, что код отправлен и куда (номер = введённый).
    await waitCodeScreen();
    await expect(byText(CODE_HINT)).toBeDisplayed();
    await expect(byText(SENT_TO(OTP_PHONE))).toBeDisplayed({ wait: 10000 });
    for (let n = 1; n <= 6; n++) await expect(digitCell(n)).toBeExisting();
    await expect(byText(RESEND)).toBeDisplayed();
    await expectNoTestMode();                                   // реджект #41747e: обходного режима нет

    // #5623bc / F-88 AC4: неверный код сразу → «неверный», остаёмся на экране, цифры не стёрты.
    await typeCode(BAD_CODE);
    await tapSubmit();
    await expectHebrewMessage('הקוד שהוזן אינו נכון');
    await expect(byText(WRONG_CODE)).toBeDisplayed();
    await expect(byTextContains(EXPIRED_CODE)).not.toBeExisting();
    await expect(byText(SENT_TO(OTP_PHONE))).toBeDisplayed();  // всё тот же экран кода
    expect(await cellValues()).toBe(BAD_CODE);

    // F-39 AC4 / S-11 AC5: «שלח קוד מחדש» доступна после ошибки (нажимать не будем — это ещё одно SMS; resend — Q-22).
    const resend = await byText(RESEND);
    await expect(resend).toBeDisplayed();
    expect(await resend.isEnabled()).toBe(true);
    await expect(byText(SUBMIT)).toBeDisplayed();
  });
});
